mapper.select:
SELECT id, manufacturer_id AS manufacturerId, manufacturer_name AS manufacturerName, contact_person AS contactPerson, contact_phone AS contactPhone, email, address, license_no AS licenseNo, license_expiry AS licenseExpiry, status, remark, create_time AS createTime, update_time AS updateTime FROM spd_manufacturer WHERE del_flag = #{delFlag}
AND manufacturer_name LIKE CONCAT('%', #{query.manufacturerName}, '%')
AND contact_person LIKE CONCAT('%', #{query.contactPerson}, '%')
AND status = #{query.status}
ORDER BY create_time DESC
